16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.BusinessDay;
20	
21	import jakarta.persistence.*;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date", columnDefinition = "DATE")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
68	    private Set<Pet> pets;
69	
70	    public String getAddress() {
71	        return this.address;
72	    }
73	
74	    public void setAddress(String address) {
75	        this.address = address;
76	    }
77	
78	    public String getCity() {
79	        return this.city;
80	    }
81	
82	    public void setCity(String city) {
83	        this.city = city;
84	    }
85	
86	    public String getTelephone() {
87	        return this.telephone;
88	    }
89	
90	    public void setTelephone(String telephone) {
91	        this.telephone = telephone;
92	    }
93	
94	    public String getEmail() {
95	        return this.email;
96	    }
97	
98	    /**
99	     * Stores the email in its canonical lower-cased form so it is always persisted and
100	     * returned lower-cased, regardless of the casing supplied by the client.
101	     */
102	    public void setEmail(String email) {
103	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
104	    }
105	
106	    public LocalDate getRegistrationDate() {
107	        return this.registrationDate;
108	    }
109	
110	    public void setRegistrationDate(LocalDate registrationDate) {
111	        this.registrationDate = registrationDate;
112	    }
113	
114	    public String getCustomerCode() {
115	        return this.customerCode;
116	    }
117	
118	    public void setCustomerCode(String customerCode) {
119	        this.customerCode = customerCode;
120	    }
121	
122	    public String getHouseholdId() {
123	        return this.householdId;
124	    }
125	
126	    public void setHouseholdId(String householdId) {
127	        this.householdId = householdId;
128	    }
129	
130	    public Integer getNamesakeCount() {
131	        return this.namesakeCount;
132	    }
133	
134	    public void setNamesakeCount(Integer namesakeCount) {
135	        this.namesakeCount = namesakeCount;
136	    }
137	
138	    /**
139	     * On first persist, default the registration date to the server's current date when the
140	     * client did not supply one, then roll the effective date forward so it always falls on a
141	     * business day (a weekend moves to the following Monday).
142	     */
143	    @PrePersist
144	    private void defaultRegistrationDate() {
145	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
146	        this.registrationDate = BusinessDay.rollForward(effectiveDate);
147	    }
148	
149	    protected Set<Pet> getPetsInternal() {
150	        if (this.pets == null) {
151	            this.pets = new HashSet<>();
152	        }
153	        return this.pets;
154	    }
155	
156	    protected void setPetsInternal(Set<Pet> pets) {
157	        this.pets = pets;
158	    }
159	
160	    public List<Pet> getPets() {
161	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
162	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
163	        return Collections.unmodifiableList(sortedPets);
164	    }
165	
166	    public void setPets(List<Pet> pets) {
167	        this.pets = new HashSet<>(pets);
168	    }
169	
170	    public void addPet(Pet pet) {
171	        getPetsInternal().add(pet);
172	        pet.setOwner(this);
173	    }
174	
175	    /**
176	     * Return the Pet with the given name, or null if none found for this Owner.
177	     *
178	     * @param name to test
179	     * @return true if pet name is already in use
180	     */
181	    public Pet getPet(String name) {
182	        return getPet(name, false);
183	    }
184	
185	    /**
186	     * Return the Pet with the given name, or null if none found for this Owner.
187	     *
188	     * @param name to test
189	     * @return true if pet name is already in use
190	     */
191	    public Pet getPet(String name, boolean ignoreNew) {
192	        name = name.toLowerCase();
193	        for (Pet pet : getPetsInternal()) {
194	            if (!ignoreNew || !pet.isNew()) {
195	                String compName = pet.getName();
196	                compName = compName.toLowerCase();
197	                if (compName.equals(name)) {
198	                    return pet;
199	                }
200	            }
201	        }
202	        return null;
203	    }
204	
205	    public Pet getPet(Integer petId) {
206	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
207	    }
208	
209	    @Override
210	    public String toString() {
211	        return new ToStringCreator(this)
212	
213	            .append("id", this.getId())
214	            .append("new", this.isNew())
215	            .append("lastName", this.getLastName())
216	            .append("firstName", this.getFirstName())
217	            .append("address", this.address)
218	            .append("city", this.city)
219	            .append("telephone", this.telephone)
220	            .append("email", this.email)
221	            .toString();
222	    }
223	}
