3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (canonical region) from its city.
7	 *
8	 * <p>The city is looked up in a small, fixed city-to-region table
9	 * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}) and the matching
10	 * canonical region string is returned. Any city not present in the table — including a
11	 * {@code null} city — derives the sentinel locality {@code "UNKNOWN"}.
12	 */
13	public final class LocalityResolver {
14	
15	    /** Locality returned for any city not present in {@link #CITY_REGION}. */
16	    public static final String UNKNOWN = "UNKNOWN";
17	
18	    /** City -> canonical region; anything not listed derives {@link #UNKNOWN}. */
19	    private static final Map<String, String> CITY_REGION = Map.of(
20	        "Sydney", "NSW",
21	        "Melbourne", "VIC",
22	        "Brisbane", "QLD");
23	
24	    private LocalityResolver() {
25	    }
26	
27	    /**
28	     * Resolve the canonical region for a city.
29	     *
30	     * @param city the owner's city, possibly {@code null}
31	     * @return the canonical region string when the city is in the table, otherwise {@code "UNKNOWN"}
32	     */
33	    public static String resolve(String city) {
34	        return CITY_REGION.getOrDefault(city, UNKNOWN);
35	    }
36	}
