17	package org.springframework.samples.petclinic.util;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	
22	/**
23	 * Utility for aligning dates to business days.
24	 */
25	public final class BusinessDay {
26	
27	    private BusinessDay() {
28	    }
29	
30	    /**
31	     * Roll {@code date} forward to the next business day: a Saturday or Sunday moves to the
32	     * following Monday, while any weekday is returned unchanged.
33	     *
34	     * @param date the date to align
35	     * @return the same date when it already falls on a business day, otherwise the next Monday
36	     */
37	    public static LocalDate rollForward(LocalDate date) {
38	        DayOfWeek dayOfWeek = date.getDayOfWeek();
39	        if (dayOfWeek == DayOfWeek.SATURDAY) {
40	            return date.plusDays(2);
41	        }
42	        if (dayOfWeek == DayOfWeek.SUNDAY) {
43	            return date.plusDays(1);
44	        }
45	        return date;
46	    }
47	}
